const projectNames = `-- name: ProjectNames :many
SELECT p.id,
       t.name AS team_name,
       u.name AS owner_name,
       m.name AS methodology_name,
       pp.identifier AS parent_identifier,
       pp.name AS parent_name
FROM projects p
JOIN teams t ON t.id = p.team_id
JOIN users u ON u.id = p.owner_id
LEFT JOIN methodologies m ON m.id = p.methodology_id
LEFT JOIN projects pp ON pp.id = p.parent_id
WHERE p.id = ANY ($1::uuid[])
`

type ProjectNamesRow struct {
	ID               uuid.UUID
	TeamName         string
	OwnerName        string
	MethodologyName  *string
	ParentIdentifier *string
	ParentName       *string
}

// Names of the related records a project view shows.
func (q *Queries) ProjectNames(ctx context.Context, ids []uuid.UUID) ([]ProjectNamesRow, error) {
	rows, err := q.db.Query(ctx, projectNames, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProjectNamesRow
	for rows.Next() {
		var i ProjectNamesRow
		if err := rows.Scan(
			&i.ID,
			&i.TeamName,
			&i.OwnerName,
			&i.MethodologyName,
			&i.ParentIdentifier,
			&i.ParentName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const projectSubtree = `-- name: ProjectSubtree :many
WITH RECURSIVE tree AS (
    SELECT p.id FROM projects p WHERE p.parent_id = $1
    UNION ALL
    SELECT c.id FROM projects c JOIN tree ON c.parent_id = tree.id
)
SELECT p.id, p.parent_id, p.identifier, p.name, p.lifecycle, p.health, p.depth, p.is_template
FROM projects p JOIN tree ON tree.id = p.id
ORDER BY p.depth, p.name
`

type ProjectSubtreeRow struct {
	ID         uuid.UUID
	ParentID   *uuid.UUID
	Identifier string
	Name       string
	Lifecycle  string
	Health     string
	Depth      int16
	IsTemplate bool
}

// Every descendant of a project, in one query (RF-28).
func (q *Queries) ProjectSubtree(ctx context.Context, parentID *uuid.UUID) ([]ProjectSubtreeRow, error) {
	rows, err := q.db.Query(ctx, projectSubtree, parentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProjectSubtreeRow
	for rows.Next() {
		var i ProjectSubtreeRow
		if err := rows.Scan(
			&i.ID,
			&i.ParentID,
			&i.Identifier,
			&i.Name,
			&i.Lifecycle,
			&i.Health,
			&i.Depth,
			&i.IsTemplate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const projectSubtreeHeight = `-- name: ProjectSubtreeHeight :one
WITH RECURSIVE tree AS (
    SELECT p.id, 0 AS level FROM projects p WHERE p.id = $1
    UNION ALL
    SELECT c.id, tree.level + 1 FROM projects c JOIN tree ON c.parent_id = tree.id WHERE tree.level < 10
)
SELECT max(level)::int FROM tree
`

// Levels below the project (0 for a leaf).
func (q *Queries) ProjectSubtreeHeight(ctx context.Context, id uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, projectSubtreeHeight, id)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

